PRACTICE_STEPS=[
 {'title':'Стартовая последовательность','details':'Три светодиода по очереди по 0,3 с, затем все выключены, ожидание 1 с; только после этого ехать.','points':2},
 {'title':'Остановки у зон 0…9','details':'Движение по разметке, проекция робота пересекает нужный жёлтый квадрат при полной остановке ≥1 c.','points':10},
 {'title':'Толкание одиночных кубиков','details':'Вытолкнуть за красную зону четыре отдельных кубика.','points':8},
 {'title':'Сохранение башенок','details':'Не сдвинуть и не коснуться границ красных клеток башенками.','points':4},
 {'title':'Финиш и итоговая индикация','details':'Прибыть в «КОНТРОЛЬ», остановиться; каждый LED соответствует чётности суммы исходных номеров клеток.','points':5},
 {'title':'Э3, код и сборка','details':'Принципиальная схема (3), читаемая компилируемая программа (2), механическая надёжность (1).','points':6},
]
BANK=[]; rng=random.Random(20261112)
def fmt(x,d=0):
 if isinstance(x,str):return x
 if d==0:return str(int(round(x)))
 return f'{x:.{d}f}'.replace('.',',')
def add(topic,question,answer,solution,hint,unit='',d=0,difficulty='Средний',kind=None):
 if kind is None:kind='number' if len(BANK)%5==0 else 'choice'
 item=dict(id=f'Q{len(BANK)+1:03}',topic=topic,question=question,answer=answer,display=fmt(answer,d),unit=unit,solution=solution,hint=hint,difficulty=difficulty,kind=kind,decimals=d)
 if kind=='choice':
  v=float(answer); scale=max(1 if d==0 else 10**(-d), abs(v)*(.07 if d==0 else .09)); wrong=[]
  offsets=[-2,-1,1,2,3,-3,4,5,-4,6]
  for off in offsets:
   z=round(v+off*scale,d)
   if d==0:z=int(z)
   if z<0 and v>=0:continue
   if abs(z-v)<(0.5*10**(-d)):continue
   if fmt(z,d) not in {fmt(y,d) for y in wrong}:wrong.append(z)
   if len(wrong)==3:break
  if len(wrong)<3:
   for off in [1,2,3,4,5]:
    z=round(v+off*10**(-d),d)
    if z!=v and fmt(z,d) not in {fmt(y,d) for y in wrong}:wrong.append(z)
    if len(wrong)==3:break
  options=[answer,*wrong[:3]];rng.shuffle(options)
  item['options']=[fmt(z,d) for z in options];item['correct']=next(i for i,z in enumerate(options) if abs(float(z)-float(answer))<=10**(-d)*.01)
 BANK.append(item)
def add_text(topic,question,options,correct,solution,hint,difficulty='База'):
 opts=list(options); assert len(opts)==4 and len(set(opts))==4 and correct in opts
 rng.shuffle(opts)
 BANK.append(dict(id=f'Q{len(BANK)+1:03}',topic=topic,question=question,options=opts,correct=opts.index(correct),answer=correct,display=correct,unit='',solution=solution,hint=hint,difficulty=difficulty,kind='choice',decimals=0))

T='Единицы и тригонометрия'
for i in range(10):
 k=i%5
 if k==0:
  a=2+i; add(T,f'Робот проехал {a} км. Сколько это метров?',1000*a,f'1 км = 1000 м: {a}·1000 = {a*1000} м.','Умножь километры на тысячу.','м',difficulty='База')
 elif k==1:
  a=45+15*(i//5); add(T,f'Угол поворота равен {a}°. Сколько это радиан, если π≈3,14? Ответ до сотых.',round(a*3.14/180,2),f'θрад = {a}·3,14/180 ≈ {a*3.14/180:.2f}.','Для градусов и радиан служит коэффициент π/180.','рад',d=2,difficulty='База')
 elif k==2:
  a=3+i;add(T,f'Скорость {a} м/с. Вырази её в мм/с.',a*1000,f'1 м = 1000 мм, поэтому v={a*1000} мм/с.','В одной секунде ничего не меняется.','мм/с',difficulty='База')
 elif k==3:
  a=2+i;add(T,f'Сколько квадратных метров занимает {a} гектаров?',a*10000,f'1 га = 10 000 м² ⇒ {a*10000} м².','Площадь 100 м × 100 м.','м²',difficulty='База')
 else:
  a=2+i;add(T,f'Колесо повернулось на {a} полных оборотов. Сколько это градусов?',360*a,f'Один оборот — 360°, получаем {a}·360={360*a}°.','Один оборот равен 2π радиан.','°',difficulty='База')

T='Шестерни и передачи'
for i in range(10):
 k=i%5
 if k==0:
  z1=12+i;z2=2*z1;n=16+i*2;add(T,f'Ведущая шестерня имеет {z1} зубьев и делает {n} оборотов; ведомая имеет {z2}. Сколько оборотов у ведомой?',n//2,f'n₂=n₁z₁/z₂={n}·{z1}/{z2}={n//2}.','Чем больше зубьев у ведомой, тем меньше скорость.','оборотов',difficulty='База')
 elif k==1:
  z=24+i*2; kstart=2; n=z//2; add(T,f'Червяк имеет {kstart} захода, колесо — {z} зубьев. Сколько оборотов червяка нужны для одного оборота колеса?',n,f'За оборот червяк сдвигает на {kstart} зуба, нужно {z}/{kstart}={n} оборотов.','Сопоставь число заходов червяка с количеством зубьев ведомой.','оборотов')
 elif k==2:
  N=8+i;red=4;add(T,f'На входе редуктора {red}:1 частота {N*red} об/мин. Чему равна частота выходного вала?',N,f'Редуктор уменьшает скорость: {N*red}/{red}={N} об/мин.','Редуктор не мультипликатор.','об/мин')
 elif k==3:
  a=5+i;add(T,f'Ведущий вал делает {a} оборотов за 10 с. Сколько оборотов он совершит за 1 минуту?',6*a,f'В минуте шесть отрезков по 10 с: {a}·6={6*a}.','Пропорция времени и числа оборотов.','оборотов',difficulty='База')
 else:
  z1=8+i;z2=2*z1;z3=16;z4=32;nin=20+i*2; add(T,f'Составная передача: {z1}→{z2} зубьев, затем колёса {z3}→{z4}. На общей оси находятся ведомое первой и ведущее второй ступени. Вход {nin} об. Сколько на выходе?',nin/4,f'Общий коэффициент ({z1}/{z2})·({z3}/{z4})=1/4; выход {nin}/4={nin/4}.','Перемножь отношения по двум зацеплениям.','оборотов',d=1)

T='Кинематика колёс'
for i in range(10):
 k=i%5
 if k==0:
  D=10+i; n=3+i; add(T,f'Колесо диаметром {D} см совершило {n} оборотов без проскальзывания. Сколько сантиметров пути? π≈3,14, ответ до сотых.',round(3.14*D*n,2),f'S=nπD={n}·3,14·{D}={3.14*D*n:.2f} см.','Длина окружности равна πD.','см',d=2,difficulty='База')
 elif k==1:
  D=8+2*i; B=D*3; theta=60;ans=theta*B/D; add(T,f'Робот разворачивается на месте на {theta}°. Колея {B} см, диаметр колеса {D} см. На сколько градусов повернётся колесо?',ans,f'α=θB/D={theta}·{B}/{D}={ans:.0f}°.','Радиус пути каждого колеса при развороте равен половине колеи.','°')
 elif k==2:
  D=10+i;B=D*2;theta=45;ans=2*theta*B/D;add(T,f'Одно колесо робота заблокировано. Колея {B} см, диаметр свободного колеса {D} см. Корпус повернулся на {theta}°. Каков угол свободного колеса?',ans,f'Вокруг неподвижного колеса α=2θB/D=2·{theta}·{B}/{D}={ans:.0f}°.','Здесь радиус поворота подвижного колеса равен колее.','°')
 elif k==3:
  vl=0.2+i*.02;vr=vl+.2;B=.5;ans=round((vr-vl)/B,2); add(T,f'Левое колесо движется {vl:.2f} м/с, правое {vr:.2f} м/с, колея {B} м. Какова угловая скорость корпуса? До сотых.',ans,f'ω=(vR−vL)/B=({vr:.2f}−{vl:.2f})/{B}=0,4 рад/с.','Для поворота важно различие скоростей.','рад/с',d=2)
 else:
  r=0.6+i*.1;B=.4;ans=round((r+B/2)*2,2); add(T,f'Маркер в центре рисует окружность радиуса {r:.1f} м, колея {B:.1f} м. Какова длина радиуса траектории левого колеса, если оно идёт снаружи, в сантиметрах?',round((r+B/2)*100),f'Радиус внешнего колеса R+B/2={r:.1f}+0,2={r+.2:.1f} м, то есть {round((r+.2)*100)} см.','Внешнее колесо дальше от центра поворота.','см')

T='Путь и графики'
for i in range(10):
 k=i%5
 if k==0:
  arr=[0,720+360*(i//5),360,1080]; tot=sum(abs(arr[j]-arr[j-1]) for j in range(1,len(arr)));add(T,f'Энкодер последовательно показал {", ".join(map(str,arr))} градусов. Сколько полных оборотов по модулю совершило колесо за всю запись?',tot/360,f'Σ|Δφ|={"+".join(str(abs(arr[j]-arr[j-1])) for j in range(1,len(arr)))}={tot}°; /360={tot/360} оборота.','Суммируй модули изменений, а не начальную и конечную разницу.','оборотов',d=1)
 elif k==1:
  V=4+i;time=10+i*2;add(T,f'Скорость линейно увеличилась от 0 до {V} м/с за {time} с. Какое расстояние пройдено?',V*time/2,f'Площадь треугольника: S={V}·{time}/2={V*time/2} м.','Площадь треугольника под v(t).','м',d=1)
 elif k==2:
  V=3+i;t=8+i;add(T,f'Робот ехал {t} с со скоростью −{V} м/с. Какой путь он прошёл?',V*t,f'S=|v|t={V}·{t}={V*t} м.','Путь не может быть отрицательным.','м',difficulty='База')
 elif k==3:
  h=5*(i+1);g=10;tt=round(math.sqrt(2*h/g),2);add(T,f'Тело уронили без начальной вертикальной скорости с высоты {h} м. За какое время оно упадёт? g=10, до сотых.',tt,f't=√(2h/g)=√({2*h}/10)={tt:.2f} с.','Используй формулу h=gt²/2.','с',d=2)
 else:
  V=4+i;t1=3+i;t2=2+i;S=V*(t1+t2/2);add(T,f'График скорости: сначала робот ехал {t1} с с постоянной скоростью {V} м/с, затем за {t2} с линейно замедлился до нуля. Найди весь путь.',S,f'Прямоугольник {V}·{t1} плюс треугольник {V}·{t2}/2: S={S} м.','Сумма площадей двух фигур под графиком.','м',d=1)

T='Моменты сил'
for i in range(10):
 k=i%5
 if k==0:
  F=10+i*2;shoulder=.3+i*.05;ans=round(F*shoulder,2);add(T,f'К стержню перпендикулярно приложена сила {F} Н на расстоянии {shoulder:.2f} м от оси. Момент силы до сотых?',ans,f'M=F·l={F}·{shoulder:.2f}={ans:.2f} Н·м.','При перпендикулярной силе плечо равно расстоянию.','Н·м',d=2,difficulty='База')
 elif k==1:
  m=200+10*i;L=40;lever=20;target=m*lever/10;add(T,f'Балка массой {m} г действует плечом {lever} см вправо от опоры. Какую массу надо повесить слева на плече 10 см для равновесия?',target,f'm·10={m}·{lever}; m={target:.0f} г.','Сумма моментов относительно опоры равна нулю.','г')
 elif k==2:
  m=.4+i*.05;L=.5;g=10;ans=round(m*g*L/2,2);add(T,f'Однородное горизонтальное звено длиной {L} м и массой {m:.2f} кг закреплено с одного конца. Каков момент его веса у основания при g={g}?',ans,f'Вес действует в середине: M=mgL/2={m:.2f}·{g}·{L}/2={ans:.2f} Н·м.','Центр масс на середине звена.','Н·м',d=2)
 elif k==3:
  m=.5+i*.1;g=10; theta=45; ans=round(m*g/2,2);add(T,f'Вертикальный стержень массы {m:.2f} кг удерживают горизонтальной силой на конце при отклонении 45° от вертикали. Чему равна сила? g=10. До сотых.',ans,f'F=(mg/2)tan45°={m:.2f}·10/2={ans:.2f} Н.','Сопоставь моменты веса в середине и силы на конце.','Н',d=2)
 else:
  m=2+i;h=.2;g=10;ans=round(m*g*h*.5,1);add(T,f'У робота масса {m} кг, центр масс на высоте {h} м. Отклонение таково, что sinθ=0,5. Момент силы тяжести?',ans,f'M=mgh sinθ={m}·10·0,2·0,5={ans:.1f} Н·м.','Вес проходит через центр масс.','Н·м',d=1)

T='Силы и трение'
for i in range(10):
 k=i%5
 if k==0:
  m=2+i;g=10;mu=.2;ans=round(m*g*mu,1);add(T,f'Горизонтальная поверхность, масса робота {m} кг, коэффициент трения {mu}, g=10. Сила трения скольжения?',ans,f'F=μmg={mu}·{m}·10={ans:.1f} Н.','На горизонтали N≈mg.','Н',d=1,difficulty='База')
 elif k==1:
  m=2+i; theta=30;mu=.2;ans=round(m*10*(.5+mu*math.sqrt(3)/2),2);add(T,f'Платформа массой {m} кг поднимается без ускорения по склону 30°, μ=0,2, g=10. Нужная тяга до сотых?',ans,f'F=mg(sin30°+μcos30°)={m}·10·(0,5+0,2·0,866025)≈{ans:.2f} Н.','Против мотора направлены составляющая веса и трение.','Н',d=2)
 elif k==2:
  torque=.2+i*.05;r=.1;ans=round(torque/r,2);add(T,f'Крутящий момент колеса {torque:.2f} Н·м, радиус {r} м. Какова идеальная сила тяги одного колеса?',ans,f'F=M/r={torque:.2f}/{r}={ans:.2f} Н.','Размерности: Н·м / м = Н.','Н',d=2)
 elif k==3:
  F=12+i;v=2;ans=F*v;add(T,f'Робот едет равномерно при тяге {F} Н со скоростью {v} м/с. Какая механическая мощность?',ans,f'P=Fv={F}·{v}={ans} Вт.','Мощность — скорость выполнения работы.','Вт',difficulty='База')
 else:
  m=4+i; mu=.5;ans=round(mu*m*10,1);add(T,f'Робот массой {m} кг на горизонтальной дороге, μ={mu}, g=10. Верхняя оценка сцепления с покрытием?',ans,f'Fсц≤μmg={mu}·{m}·10={ans:.1f} Н.','Для предельного сцепления нужна нормальная реакция.','Н',d=1)

T='Электрические цепи'
for i in range(10):
 k=i%5
 if k==0:
  I=.1+i*.01;R=100;ans=round(I*R,2);add(T,f'Через резистор {R} Ом течёт ток {I:.2f} А. Каково напряжение? До сотых.',ans,f'U=IR={I:.2f}·{R}={ans:.2f} В.','Закон Ома.','В',d=2,difficulty='База')
 elif k==1:
  R1=100+i*10;R2=200+i*10;ans=R1+R2;add(T,f'Резисторы {R1} и {R2} Ом соединены последовательно. Общее сопротивление?',ans,f'R={R1}+{R2}={ans} Ом.','Последовательное соединение — сложение сопротивлений.','Ом',difficulty='База')
 elif k==2:
  R=100+20*i;ans=R/2;add(T,f'Два одинаковых резистора по {R} Ом подключены параллельно. Общее сопротивление?',ans,f'Для двух одинаковых сопротивлений параллельно Rэкв=R/2={R}/2={ans} Ом.','Параллельное соединение одинаковых резисторов уменьшает значение вдвое.','Ом')
 elif k==3:
  U=12; Rtop=100+i*10;Rdown=Rtop;ans=6;add(T,f'Делитель питается от {U} В; верхний и нижний резисторы по {Rtop} Ом. Напряжение средней точки?',ans,f'Uвых={U}·{Rdown}/({Rtop}+{Rdown})=6 В.','Равные плечи делителя делят напряжение поровну.','В',difficulty='База')
 else:
  U=5;Ud=2;I=.01;ans=300;add(T,f'LED питается от 5 В через резистор, падение на LED 2 В, желаемый ток 10 мА. Найти сопротивление.',ans,f'R=(5−2)/0,01=300 Ом.','Выдели напряжение на резисторе.','Ом')

T='Алгоритмы и циклы'
for i in range(10):
 k=i%5
 if k==0:
  x=3+i;d=5;ans=x%d;add(T,f'Чему равен остаток от деления {x} на {d}?',ans,f'{x}={x//d}·{d}+{ans}, остаток {ans}.','Остаток меньше положительного делителя.','',difficulty='База')
 elif k==1:
  n=5+i;ans=n*(n-1)//2;add(T,f'Сколько неупорядоченных пар можно образовать из {n} различных объектов?',ans,f'C({n},2)={n}·{n-1}/2={ans}.','Каждую пару при простом переборе посчитаешь дважды.','пар')
 elif k==2:
  a=2+i;steps=4;ans=a*2**steps;add(T,f'Переменная x={a}. Цикл повторяется {steps} раза: x = 2·x. Каково конечное значение x?',ans,f'Каждая итерация удваивает: x={a}·2⁴={ans}.','Сделай таблицу x после каждого прохода.','',difficulty='База')
 elif k==3:
  n=6+i;ans=n*n;add(T,f'Два вложенных цикла выполняются по {n} раз каждый. Сколько всего выполнений тела внутреннего цикла?',ans,f'{n}·{n}={ans} выполнений.','Число операций перемножается при вложении циклов.','раз')
 else:
  n=3+i;ans=2*n*(n-1);add(T,f'{n} попарно пересекающихся прямоугольников описанного в учебнике типа дают 4 точки на каждую пару. Сколько точек пересечения контуров?',ans,f'4C({n},2)=2·{n}·({n}−1)={ans}.','Считай пары прямоугольников.','точек')

T='Площади и объёмы'
for i in range(10):
 k=i%5
 if k==0:
  r=2+i;ans=round(3.14*r*r,2);add(T,f'Радиус круга {r} см. Площадь при π≈3,14, до сотых?',ans,f'A=πr²=3,14·{r}²={ans:.2f} см².','В формуле площади радиус в квадрате.','см²',d=2,difficulty='База')
 elif k==1:
  r=2+i;h=10;ans=round(3.14*r*r*h,2);add(T,f'Радиус цилиндра {r} см, высота {h} см. Объём при π≈3,14?',ans,f'V=πr²h=3,14·{r}²·{h}={ans:.2f} см³.','Площадь основания умножить на высоту.','см³',d=2)
 elif k==2:
  a=5+i;b=6;ans=a*b-1;add(T,f'Территория — сетка из {a}×{b} квадратных клеток. Нужно пройти все клетки «змейкой» от центра к центру соседних клеток. Минимум переходов?',ans,f'Всего {a}·{b}={a*b} клеток; змейка посещает без повторений, переходов {a*b}−1={ans}.','Между N разными клетками нужно минимум N−1 переходов.','переходов')
 elif k==3:
  r1=10+i;r2=r1*2;ans=8;add(T,f'Радиус подобного шара увеличили в 2 раза. Во сколько раз возрастёт масса при той же плотности?',ans,'Объём шара и масса при постоянной плотности пропорциональны кубу линейного масштаба: 2³=8.','Для объёма показатель степени три.','раз',difficulty='База')
 else:
  R=10+i;r=5;h=10;ans=round(.5*3.14*(R*R-r*r)*h,2);add(T,f'Рабочая область — половина полого цилиндра: R={R} см, r={r} см, h={h} см. Найти объём при π=3,14.',ans,f'V=(π/2)(R²−r²)h=1,57·({R}²−25)·10={ans:.2f} см³.','Вычти внутренний цилиндр из внешнего.','см³',d=2)

T='Камеры и зрение'
for i in range(10):
 k=i%5
 if k==0:
  f=100+i*10;H=2;Z=4;ans=f/2;add(T,f'Камера имеет f={f} пикселей, объект высотой {H} м находится в {Z} м. Размер на кадре?',ans,f'h=fH/Z={f}·{H}/{Z}={ans:.0f} px.','Используй пропорциональность H/Z.','px',difficulty='База')
 elif k==1:
  h=60;Z=3+i;H=2;ans=h*Z/H;add(T,f'Объект высотой {H} м на расстоянии {Z} м занимает {h} px. Чему равно фокусное расстояние в пикселях?',ans,f'f=hZ/H={h}·{Z}/{H}={ans:.0f} px.','Переставь члены формулы h=fH/Z.','px')
 elif k==2:
  H=3+i;f=120;Z=6;ans=H*20;add(T,f'Башня высотой {H} м находится на расстоянии 6 м. При f=120 px какой высоты изображение?',ans,f'h=120·{H}/6={ans} px.','Фокусное расстояние задаётся в пикселях.','px')
 elif k==3:
  h=100+i*10;factor=2;ans=h/2;add(T,f'Объект занимает {h} пикселей, затем его отодвинули вдвое дальше (ракурс не меняется). Новый размер?',ans,f'Величина изображения обратно пропорциональна расстоянию, поэтому {h}/2={ans} px.','Модель pinhole.','px')
 else:
  area=4;ans=8;add(T,'При неизменной глубине площадь проекции шара увеличилась в 4 раза. Во сколько раз увеличилась его масса при той же плотности?',ans,'Радиус вырос в √4=2 раза, объём/масса выросли в 2³=8 раз.','Масса растёт быстрее площади.','раз')

T='Навигация и полёт'
for i in range(10):
 k=i%5
 if k==0:
  a=3*(i+1);b=4*(i+1);c=5*(i+1);add(T,f'Коптер переместился на {a} м к востоку и {b} м к северу. Удаление от точки старта?',c,f'd=√({a}²+{b}²)={c} м по тройке 3–4–5.','Пифагор по перпендикулярным направлениям.','м',difficulty='База')
 elif k==1:
  R=5+i;d=3+i;L=2*math.sqrt(R*R-d*d);add(T,f'Круг радара имеет радиус {R} км; прямая траектория проходит на расстоянии {d} км от центра. Длина хорды до сотых?',round(L,2),f'L=2√(R²−d²)=2√({R}²−{d}²)≈{L:.2f} км.','Перпендикуляр к хорде делит её пополам.','км',d=2)
 elif k==2:
  omega=30+i*5;t=6;ans=omega*t;add(T,f'Радар вращается {omega}°/с. Какой угол он пройдёт за {t} секунд?',ans,f'φ=Ωt={omega}·{t}={ans}°.','Угловая скорость умножается на время.','°',difficulty='База')
 elif k==3:
  N=2+i;ans=round(N*math.sqrt(2),2);add(T,f'Коптер летит {N*2} км строго на северо-восток. Сколько километров составляющая на восток? До сотых.',ans,f'Проекция Lcos45°={N*2}/√2≈{ans:.2f} км.','Равные проекции при 45°.','км',d=2)
 else:
  R=2+i;omega=math.pi/6;ans=round(R*omega,2);add(T,f'Луч вращается со скоростью 30°/с. Какова линейная скорость его точки на расстоянии {R} м от оси? До сотых.',ans,f'ω=30π/180=π/6 рад/с; v=rω={R}·π/6≈{ans:.2f} м/с.','Для v=rω требуется ω в радианах/с.','м/с',d=2)

T='Теория управления'
for i in range(10):
 k=i%5
 if k==0:
  F=100*(i+1);coef=1;ans=round(math.sqrt(F/coef),2);add(T,f'Сила разгона {F} Н, сопротивление Fтр=1·v². Предельная скорость? До сотых.',ans,f'В пределе {F}=v², поэтому vmax=√{F}≈{ans:.2f} м/с.','Предельная скорость при нулевом ускорении.','м/с',d=2)
 elif k==1:
  F=400+i*100;coef=1;ans=round(math.sqrt(F/coef)/2,2);add(T,f'Сила разгона {F} Н, сопротивление v². При какой скорости включить датчик, если нужна половина vmax?',ans,f'vmax=√{F}, половина — √{F}/2≈{ans:.2f} м/с.','Сначала найди vmax, затем раздели скорость пополам.','м/с',d=2)
 elif k==2:
  C=9;P=.01;ans=21;add(T,'Для M(m)=−0,01m+m/(m+9), m положительное целое. При каком m максимум?',21,'Производная: −0,01+9/(m+9)²=0 ⇒ m+9=30, m=21; проверь соседей.','Непрерывный максимум, затем соседние целые.','модулей',difficulty='Продвинутый')
 elif k==3:
  K=2+i;e=3;ans=K*e;add(T,f'У пропорционального регулятора Kp={K}, ошибка e={e}. Чему равен u=Kp·e?',ans,f'u=Kp·e={K}·{e}={ans}.','Пропорциональная часть зависит от текущей ошибки.','',difficulty='База')
 else:
  m=4+i;h=.3;g=10;tan=.1;ans=1;add(T,'Балансирующий робот удерживается при отклонении, для которого tanθ=0,1. Каким должно быть горизонтальное ускорение для компенсации? g=10.',ans,'a=g·tanθ=10·0,1=1 м/с²; масса и высота в простой модели сокращаются.','Приравняй моменты веса и компенсирующего ускорения.','м/с²')

T='Статистика'
for i in range(10):
 k=i%5
 if k==0:
  a=i+2;arr=[a-2,a,a+2];ans=a;add(T,f'Датчик измерил {arr[0]}, {arr[1]}, {arr[2]}. Найди среднее.',ans,f'Среднее ({arr[0]}+{arr[1]}+{arr[2]})/3={ans}.','Сложи все измерения и раздели на количество.','',difficulty='База')
 elif k==1:
  a=i+5;xs=[a-1,a+1];ans=1;add(T,f'Измерения {xs[0]} и {xs[1]}. Найди σ при делении дисперсии на n.',ans,'Среднее посередине. Отклонения −1,+1, их квадраты по 1, σ=√1=1.','Используется деление на n, не на n−1.','',difficulty='База')
 elif k==2:
  a=i+8;ans=2;add(T,f'Измерения {a-2}, {a}, {a+2}. Какова дисперсия с делением на n? Ответ до сотых.',round(8/3,2),'Среднее равно центру, квадраты отклонений 4,0,4; дисперсия 8/3≈2,67.','Сначала найди среднее.','',d=2)
 elif k==3:
  xs=[8,9,9,10,13,13,15];ans=5;add(T,'Данные: 8,9,9,10,13,13,15. Удалить значения дальше одного исходного σ от исходного среднего. Сколько останется?',5,'x̄=11, σ≈2,45, остаются 9,9,10,13,13: пять значений.','Не пересчитывай σ после каждого исключения.','измерений')
 else:
  a=1+i;ans=0;add(T,f'Выборка: {a}, {a}, {a}. Чему равно стандартное отклонение?',0,'Все значения равны среднему; каждый квадрат отклонения 0 ⇒ σ=0.','Нулевой разброс означает одинаковые наблюдения.','',difficulty='База')

T='Манипуляторы'
for i in range(10):
 k=i%5
 if k==0:
  L1=20+i;L2=30;ans=L1+L2;add(T,f'Плоский манипулятор с двумя свободными звеньями длиной {L1} и {L2} см. Максимальный вылет?',ans,f'При полном выпрямлении Rmax={L1}+{L2}={ans} см.','Выпрями оба звена в одну линию.','см',difficulty='База')
 elif k==1:
  L1=30+i;L2=10;ans=L1-L2;add(T,f'Два вращательных звена {L1} и {L2} см, оба могут свободно поворачиваться. Минимальное расстояние от основания до кончика?',ans,f'Согни звенья в противоположные стороны: Rmin=|{L1}−{L2}|={ans} см.','Минимум при противоположной ориентации звеньев.','см')
 elif k==2:
  mass=.1+i*.02;L=20;ans=round(mass*(L/2),2);add(T,f'Горизонтальное звено массой {mass:.2f} кг и длиной {L} см однородно. Какой момент веса в кгс·см относительно начала?',ans,f'Центр массы в {L/2:.0f} см; M={mass:.2f}·{L/2:.0f}={ans:.2f} кгс·см.','Вес однородного звена приложен в его середине.','кгс·см',d=2)
 elif k==3:
  N=4+i; s=100;ans=N*s;add(T,f'Шагающий робот делает {N} шагов по {s} мм без поворота. Расстояние от начала?',ans,f'При δ=0 все шаги сонаправлены: D={N}·{s}={ans} мм.','В пределе нулевого угла сумма шагов — прямая.','мм',difficulty='База')
 else:
  span=180;ans=50;add(T,'Манипулятор вращается вокруг вертикальной оси на 180° вместо 360°. Какую долю в процентах от полного объёма вращения составляет рабочая область при остальных одинаковых параметрах?',ans,'180/360=1/2 ⇒ 50% от полного объёма.','Сравни углы поворота.','%',difficulty='База')

T='Практика Arduino'
for i in range(10):
 k=i%5
 if k==0:
  vals=[0,2,4,6];ans=0;add(T,f'У робота одиночные кубики в клетках {vals}. Какое двоичное значение LED1 (светится=1)?',ans,f'Сумма 0+2+4+6=12 чётная, значит LED1=0.','LED отражает чётность суммы индексов, не количество кубиков.','0/1',difficulty='База')
 elif k==1:
  v=[0,1,2,3];ans=0;add(T,'Одиночные кубики стоят в зонах 0,1,2,3. LED1 должен светиться (1) или нет (0)?',ans,'0+1+2+3=6 — чётная сумма, LED1 выключен.','Сложи номера исходных зон.','0/1',difficulty='База')
 elif k==2:
  n=3+i;ans=3*n;add(T,f'Робот проверяет {n} контрольных зон, на каждой делает 3 независимых измерения. Сколько измерений в сумме?',ans,f'{n}·3={ans}.','Простой подсчёт циклов.','измерений',difficulty='База')
 elif k==3:
  per=.3;wait=1;ans=1.9;add(T,'На старте три LED включаются строго последовательно каждый на 0,3 с, затем робот ждёт 1 с. Через сколько секунд можно начинать движение?',ans,'3·0,3+1=1,9 с.','Последовательные выдержки складываются.','с',d=1,difficulty='База')
 else:
  n=10;filled=7;ans=3;add(T,'В 10 контрольных зонах четыре одиночных кубика, две башенки из двух и одна башенка из трёх (каждый объект в отдельной зоне). Сколько зон пусты?',3,'Всего занято 4+2+1=7 зон из 10. Пустых 10−7=3.','Башенка занимает одну зону независимо от высоты.','зон',difficulty='База')

assert len(BANK)==150,len(BANK)
for q in BANK:
 if q['kind']=='choice':
  assert len(q['options'])==4 and len(set(q['options']))==4,(q['id'],q['options'])
  assert 0<=q['correct']<=3
  assert q['options'][q['correct']]==q['display'],(q['id'],q['options'],q['display'])
 else:assert isinstance(q['answer'],(int,float))

